import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input:    { fill: '#e8f5e9', stroke: '#4caf50' },
  encoder:  { fill: '#e3f2fd', stroke: '#1976d2' },
  retrieval:{ fill: '#f3e5f5', stroke: '#7b1fa2' },
  document: { fill: '#fff3e0', stroke: '#e65100' },
  augment:  { fill: '#e0f7fa', stroke: '#00838f' },
  generate: { fill: '#fce4ec', stroke: '#c2185b' },
  output:   { fill: '#f3e5f5', stroke: '#7b1fa2' },
  weight:   { fill: '#f1f5f9', stroke: '#64748b' },
  rerank:   { fill: '#ede7f6', stroke: '#5e35b1' },
  text:    'var(--text)',
  muted:   'var(--text-muted)',
};

const BOX_H = 60;
const BOX_W = 960;
const MAT_H = 80;
const VEC_H = 40;
const VEC_W = 160;
const WEIGHT_W = 130;
const WEIGHT_H = 92;
const SEQ_W = 190;
const GROUP_GAP = 140;
const BOX_TO_ROW_GAP = 72;
const VERTICAL_ARROW_LEN = 120;
const ROW_EQ_GAP = 76;
const COL_GAP = 340;
const BYPASS_FAR_X = CX + 560;

interface RagStep extends StepInfo {}

interface RenderResult {
  steps: RagStep[];
  y: number;
  queryBypassY?: number;
}

interface RagParams {
  dModel: number;
  seqLen: number;
  kDocs: number;
  nDocs: number;
  variant: string;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, y: number, x2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function startGroup(g: Gsel, className: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string,
  width = BOX_W
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - width / 2)
    .attr('y', y)
    .attr('width', width)
    .attr('height', BOX_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  grp.append('circle')
    .attr('cx', cx - width / 2 + 22)
    .attr('cy', y + BOX_H / 2)
    .attr('r', 14)
    .attr('fill', stroke);
  lbl(grp, cx - width / 2 + 22, y + BOX_H / 2 + 1, String(stepNum), { size: 13, weight: '700', color: '#fff' });

  lbl(grp, cx - width / 2 + 44, y + BOX_H / 2 - 1, title, {
    size: 15, weight: '600', color: 'var(--text)', anchor: 'start',
  });
  lbl(grp, cx + width / 2 - 14, y + BOX_H / 2 - 1, formula, {
    size: 11, color: 'var(--text-muted)', font: 'monospace', anchor: 'end',
  });
  return y + BOX_H;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle')
    .attr('cx', cx)
    .attr('cy', cy)
    .attr('r', 16)
    .attr('fill', '#fff')
    .attr('stroke', color)
    .attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 13, weight: '700', color });
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 7.5 + 28, 160);
  const h = 28;
  g.append('rect')
    .attr('x', cx - w / 2)
    .attr('y', cy - h / 2)
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 4)
    .attr('fill', 'var(--surface)')
    .attr('stroke', color)
    .attr('stroke-width', 0.5)
    .attr('opacity', 0.85);
  lbl(g, cx, cy, text, { size: 9, color, font: 'monospace' });
}

function drawDashedPath(g: Gsel, path: string, color: string, opacity = 0.6): void {
  g.append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '6 4')
    .attr('opacity', opacity);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel, x: number, cy: number, label: string, sublabel: string,
  fill = COLORS.input.fill, stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x - SEQ_W / 2, cy - MAT_H / 2, {
    width: SEQ_W, height: MAT_H, label, sublabel, fill, stroke,
    cols: 8, rows: 5, dimTop: 'S', dimRight: 'D',
  });
}

function drawWeightMatrix(
  g: Gsel, x: number, cy: number, label: string, sublabel: string,
  fill = COLORS.weight.fill, stroke = COLORS.weight.stroke,
  width = WEIGHT_W, height = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - height / 2, {
    width, height, label, sublabel, fill, stroke, cols: 5, rows: 5,
  });
}

function drawSmallVector(
  g: Gsel, x: number, cy: number, label: string, sublabel: string,
  fill: string, stroke: string, width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - VEC_H / 2, {
    width, height: VEC_H, label, sublabel, fill, stroke, cols: 8, rows: 1,
  });
}

function drawDocIndex(
  g: Gsel, x: number, cy: number, label: string, sublabel: string,
  fill: string, stroke: string
): void {
  const w = 200;
  const h = 100;
  drawMatrixBlock(g as Sel, x - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel, fill, stroke,
    cols: 6, rows: 8, dimTop: 'N', dimRight: 'D',
  });
}

function drawLLMBox(
  g: Gsel, cx: number, cy: number, label: string, sublabel: string,
  fill: string, stroke: string
): void {
  const w = 400;
  const h = 80;
  const grp = g.append('g');
  grp.append('rect')
    .attr('x', cx - w / 2)
    .attr('y', cy - h / 2)
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 12)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 2);
  lbl(grp, cx, cy - 12, label, { size: 16, weight: '700', color: stroke });
  lbl(grp, cx, cy + 12, sublabel, { size: 10, color: COLORS.muted, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const badgeW = Math.max(90, text.length * 7.5 + 16);
  const badgeH = 36;
  g.append('rect')
    .attr('x', cx - badgeW / 2)
    .attr('y', cy - badgeH / 2)
    .attr('width', badgeW)
    .attr('height', badgeH)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 11, weight: '600', color: stroke });
}

function drawParamSummary(g: Gsel, cx: number, y: number, p: RagParams): number {
  const encParams = p.dModel * p.dModel;
  const indexSize = p.nDocs * p.dModel;
  const retrievalFlops = 2 * p.nDocs * p.dModel;
  const items = [
    `Encoder: ${fmtNum(encParams)}`,
    `Index: ${fmtNum(indexSize)}`,
    `Retrieval: ~${fmtNum(retrievalFlops)} FLOPs`,
    `top_k: ${p.kDocs}`,
  ];
  const w = BOX_W;
  const h = 32;
  const grp = g.append('g');
  grp.append('rect')
    .attr('x', cx - w / 2)
    .attr('y', y)
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    const sx = cx - w / 2 + segW * (i + 0.5);
    lbl(grp, sx, y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Shared step functions
// ═══════════════════════════════════════════════════════════════════════════════

function drawInputQueryStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-input', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Input Query',
    `query: [${p.seqLen}, ${p.dModel}]`,
    COLORS.input.fill, COLORS.input.stroke
  );
  const matCy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, matCy, 'query', `[${p.seqLen}, ${p.dModel}]`,
    COLORS.input.fill, COLORS.input.stroke);
  lbl(grp, cx, matCy + MAT_H / 2 + 18, 'tokenized user question', { size: 9, color: COLORS.muted });
  return { bottom: matCy + MAT_H / 2 + 30, outCy: matCy };
}

function drawQueryEncodingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, inputBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-qenc', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Query Encoding',
    `q_emb = mean(query @ W_enc)`,
    COLORS.encoder.fill, COLORS.encoder.stroke
  );
  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  drawWeightMatrix(grp, cx, wCy, 'W_enc', `[${p.dModel}, ${p.dModel}]`,
    COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, cx, inputBottom, wCy - WEIGHT_H / 2, COLORS.encoder.stroke);
  lbl(grp, cx + WEIGHT_W / 2 + 10, wCy, '× W_enc',
    { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  const poolY = wCy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawBadge(grp, cx, poolY - VEC_H, 'mean-pool', COLORS.encoder.fill, COLORS.encoder.stroke);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, poolY - VEC_H / 2 - 18, COLORS.encoder.stroke);

  const qembY = poolY + VEC_H / 2 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, qembY, 'q_emb', `[1, ${p.dModel}]`,
    COLORS.encoder.fill, COLORS.encoder.stroke);
  arrowDown(grp, cx, poolY + VEC_H / 2, qembY - VEC_H / 2, COLORS.encoder.stroke);

  drawShapeEq(grp, cx, qembY + VEC_H / 2 + 30,
    `query [${p.seqLen},${p.dModel}] · W_enc [${p.dModel},${p.dModel}] → [${p.seqLen},${p.dModel}] → pool → [1,${p.dModel}]`,
    COLORS.encoder.stroke);

  return { bottom: qembY + VEC_H / 2 + 48, outCy: qembY };
}

function drawDocIndexStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, label: string
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-docidx', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, label,
    `D ∈ ℝ^(${p.nDocs}, ${p.dModel})`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const docCy = headerBottom + BOX_TO_ROW_GAP + 50;
  drawDocIndex(grp, cx, docCy, 'D (doc index)', `[${p.nDocs}, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  lbl(grp, cx, docCy + 50 + 18, 'pre-computed document embeddings (FAISS/HNSW index)', { size: 9, color: COLORS.muted });
  return { bottom: docCy + 50 + 30, outCy: docCy };
}

function drawAugmentationStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  topKBottom: number, queryBypassY: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-augment', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Context Augmentation',
    `context = [docs; query]`,
    COLORS.augment.fill, COLORS.augment.stroke
  );
  const concatY = headerBottom + BOX_TO_ROW_GAP + 18;
  opCircle(grp, cx, concatY, '⊕', COLORS.augment.stroke);
  lbl(grp, cx + 22, concatY, 'concat', { size: 9, color: COLORS.muted, anchor: 'start' });
  arrowDown(grp, cx, topKBottom, concatY - 16, COLORS.retrieval.stroke);

  if (queryBypassY > 0) {
    drawDashedPath(g,
      `M ${CX - SEQ_W / 2 - 10},${queryBypassY} L ${BYPASS_FAR_X},${queryBypassY} L ${BYPASS_FAR_X},${concatY} L ${cx + 16},${concatY}`,
      COLORS.input.stroke, 0.6);
    lbl(g, BYPASS_FAR_X - 8, (queryBypassY + concatY) / 2, 'query bypass',
      { size: 9, color: COLORS.input.stroke, anchor: 'end' });
  }

  const ctxY = concatY + 18 + ROW_EQ_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, ctxY, 'context', `[(k+1)×${p.seqLen}, ${p.dModel}]`,
    COLORS.augment.fill, COLORS.augment.stroke);
  arrowDown(grp, cx, concatY + 16, ctxY - MAT_H / 2, COLORS.augment.stroke);
  lbl(grp, cx, ctxY + MAT_H / 2 + 18, 'retrieved docs + query → prompt for LLM', { size: 9, color: COLORS.muted });

  return { bottom: ctxY + MAT_H / 2 + 30, outCy: ctxY };
}

function drawGenerationStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, ctxBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-gen', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'LLM Generation',
    `answer = LLM.generate(context)`,
    COLORS.generate.fill, COLORS.generate.stroke
  );
  const llmCy = headerBottom + BOX_TO_ROW_GAP + 40;
  drawLLMBox(grp, cx, llmCy, 'LLM / Generator', `autoregressive decode · d=${p.dModel}`,
    COLORS.generate.fill, COLORS.generate.stroke);
  arrowDown(grp, cx, ctxBottom, llmCy - 40, COLORS.augment.stroke);

  const ansY = llmCy + 40 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, ansY, 'answer', `[seq_a, ${p.dModel}]`,
    COLORS.generate.fill, COLORS.generate.stroke, 180);
  arrowDown(grp, cx, llmCy + 40, ansY - VEC_H / 2, COLORS.generate.stroke);

  return { bottom: ansY + VEC_H / 2 + 24, outCy: ansY };
}

function drawOutputStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, genBottom: number
): number {
  const grp = startGroup(g, 'step-rag-output', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Output Answer',
    `answer ∈ ℝ^(seq_a)`,
    COLORS.output.fill, COLORS.output.stroke
  );
  const outY = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, outY, 'answer', `[seq_a, ${p.dModel}]`,
    COLORS.output.fill, COLORS.output.stroke, 180);
  arrowDown(grp, cx, genBottom, outY - VEC_H / 2, COLORS.output.stroke);
  return outY + VEC_H / 2 + 24;
}

// ═══════════════════════════════════════════════════════════════════════════════
// RAG Pipeline variant — similarity & retrieval step
// ═══════════════════════════════════════════════════════════════════════════════

function drawSimilarityRetrievalStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  _qEmbCy: number, _docCy: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-retrieval', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Similarity & Retrieval',
    `scores = cos(q_emb, D) → top-k`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke
  );

  const rowY = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const qX = cx - COL_GAP;
  const dX = cx + COL_GAP;

  drawSmallVector(grp, qX, rowY, 'q_emb', `[1, ${p.dModel}]`,
    COLORS.encoder.fill, COLORS.encoder.stroke);
  lbl(grp, qX, rowY + VEC_H / 2 + 14, 'encoded query', { size: 9, color: COLORS.muted });

  drawDocIndex(grp, dX, rowY, 'D', `[${p.nDocs}, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  lbl(grp, dX, rowY + 50 + 14, 'document index', { size: 9, color: COLORS.muted });

  drawBadge(grp, cx, rowY, 'cosine sim', COLORS.retrieval.fill, COLORS.retrieval.stroke);
  arrowH(grp, qX + VEC_W / 2, rowY, cx - 75, COLORS.encoder.stroke);
  arrowH(grp, dX - 100, rowY, cx + 75, COLORS.document.stroke);

  const scoresY = rowY + Math.max(VEC_H, 100) / 2 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, scoresY, 'scores', `[${p.nDocs}]`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke, 200);
  arrowDown(grp, cx, rowY + 18, scoresY - VEC_H / 2, COLORS.retrieval.stroke);
  lbl(grp, cx + 110, scoresY, 'cos(q, d_i) ∀i', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  const topkBadgeY = scoresY + VEC_H / 2 + ROW_EQ_GAP / 2 + 18;
  drawBadge(grp, cx, topkBadgeY, `top-k (k=${p.kDocs})`, COLORS.retrieval.fill, COLORS.retrieval.stroke);
  arrowDown(grp, cx, scoresY + VEC_H / 2, topkBadgeY - 18, COLORS.retrieval.stroke);

  const topkY = topkBadgeY + 18 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, topkY, 'top_k_docs', `[${p.kDocs}, ${p.dModel}]`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke, 200);
  arrowDown(grp, cx, topkBadgeY + 18, topkY - VEC_H / 2, COLORS.retrieval.stroke);
  lbl(grp, cx, topkY + VEC_H / 2 + 14, 'most relevant doc embeddings', { size: 9, color: COLORS.muted });

  drawShapeEq(grp, cx, topkY + VEC_H / 2 + 38,
    `q_emb [1,${p.dModel}] · D^T [${p.dModel},${p.nDocs}] → scores [${p.nDocs}] → top-k [${p.kDocs}]`,
    COLORS.retrieval.stroke);

  return { bottom: topkY + VEC_H / 2 + 64, outCy: topkY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Chunking variant step functions
// ═══════════════════════════════════════════════════════════════════════════════

function drawRawDocStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-rawdoc', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Raw Document',
    `raw_doc: [${p.seqLen * 4}, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const docCy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const w = 220;
  drawMatrixBlock(grp as Sel, cx - w / 2, docCy - MAT_H / 2, {
    width: w, height: MAT_H, label: 'raw_doc', sublabel: `[${p.seqLen * 4}, ${p.dModel}]`,
    fill: COLORS.document.fill, stroke: COLORS.document.stroke, cols: 10, rows: 5,
    dimTop: '4·S', dimRight: 'D',
  });
  lbl(grp, cx, docCy + MAT_H / 2 + 18, 'source document to be indexed', { size: 9, color: COLORS.muted });
  return { bottom: docCy + MAT_H / 2 + 30, outCy: docCy };
}

function drawChunkingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, rawDocBottom: number
): { bottom: number; chunksCy: number; chunkXs: number[] } {
  const grp = startGroup(g, 'step-rag-chunk', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Document Chunking',
    `chunks = split(raw_doc, size=${p.seqLen})`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const chunkCy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const gap = 280;
  const xs = [cx - gap, cx, cx + gap];
  const labels = ['chunk_0', 'chunk_1', 'chunk_2'];

  xs.forEach((x, i) => {
    drawSeqMatrix(grp, x, chunkCy, labels[i], `[${p.seqLen}, ${p.dModel}]`,
      COLORS.document.fill, COLORS.document.stroke);
    drawDashedPath(grp,
      `M ${cx},${rawDocBottom} L ${cx},${chunkCy - MAT_H / 2 - 10} L ${x},${chunkCy - MAT_H / 2 - 10} L ${x},${chunkCy - MAT_H / 2}`,
      COLORS.document.stroke, 0.4);
  });
  lbl(grp, cx, chunkCy + MAT_H / 2 + 18, 'overlapping chunks (stride < chunk_size for continuity)', { size: 9, color: COLORS.muted });

  return { bottom: chunkCy + MAT_H / 2 + 30, chunksCy: chunkCy, chunkXs: xs };
}

function drawChunkEncodingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  chunksCy: number, chunkXs: number[]
): { bottom: number; embsCy: number; embXs: number[] } {
  const grp = startGroup(g, 'step-rag-chunkenc', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Chunk Encoding',
    `emb_i = mean(chunk_i @ W_enc)`,
    COLORS.encoder.fill, COLORS.encoder.stroke
  );
  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;

  chunkXs.forEach((x) => {
    drawWeightMatrix(grp, x, wCy, 'W_enc', `[${p.dModel},${p.dModel}]`,
      COLORS.weight.fill, COLORS.weight.stroke, 90, 60);
    arrowDown(grp, x, chunksCy + MAT_H / 2, wCy - 30, COLORS.encoder.stroke);
  });

  const embY = wCy + 30 + ROW_EQ_GAP + VEC_H / 2;
  const embXs = chunkXs;
  embXs.forEach((x, i) => {
    drawSmallVector(grp, x, embY, `emb_${i}`, `[1, ${p.dModel}]`,
      COLORS.encoder.fill, COLORS.encoder.stroke, 100);
    arrowDown(grp, x, wCy + 30, embY - VEC_H / 2, COLORS.encoder.stroke);
  });
  lbl(grp, cx, embY + VEC_H / 2 + 14, 'each chunk → mean-pooled embedding', { size: 9, color: COLORS.muted });

  return { bottom: embY + VEC_H / 2 + 30, embsCy: embY, embXs };
}

function drawIndexBuildingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  embsCy: number, embXs: number[]
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-index', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Index Building',
    `index = stack(emb_0, emb_1, emb_2)`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const idxCy = headerBottom + BOX_TO_ROW_GAP + 50;
  drawDocIndex(grp, cx, idxCy, 'index', `[3, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  embXs.forEach((x) => {
    drawDashedPath(grp,
      `M ${x},${embsCy + VEC_H / 2} L ${x},${idxCy - 60} L ${cx},${idxCy - 60} L ${cx},${idxCy - 50}`,
      COLORS.encoder.stroke, 0.4);
  });
  lbl(grp, cx, idxCy + 50 + 18, 'stacked chunk embeddings form the search index', { size: 9, color: COLORS.muted });
  return { bottom: idxCy + 50 + 30, outCy: idxCy };
}

function drawRetrievalMatMulStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  _qEncCy: number, _idxCy: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-matmul', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Retrieval (MatMul + Softmax)',
    `scores = q_enc @ index^T → softmax`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke
  );
  const rowY = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const qX = cx - 160;
  const iX = cx + 160;

  drawSmallVector(grp, qX, rowY, 'q_enc', `[1, ${p.dModel}]`,
    COLORS.encoder.fill, COLORS.encoder.stroke, 120);
  drawDocIndex(grp, iX, rowY, 'index', `[3, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  drawBadge(grp, cx, rowY, '@', COLORS.retrieval.fill, COLORS.retrieval.stroke);
  arrowH(grp, qX + 60, rowY, cx - 30, COLORS.encoder.stroke);
  arrowH(grp, iX - 100, rowY, cx + 30, COLORS.document.stroke);

  const scoresY = rowY + 50 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, scoresY, 'scores', `[3]`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke, 120);
  arrowDown(grp, cx, rowY + 18, scoresY - VEC_H / 2, COLORS.retrieval.stroke);

  const smBadgeY = scoresY + VEC_H / 2 + 18 + 18;
  drawBadge(grp, cx, smBadgeY, 'softmax', COLORS.retrieval.fill, COLORS.retrieval.stroke);
  arrowDown(grp, cx, scoresY + VEC_H / 2, smBadgeY - 18, COLORS.retrieval.stroke);

  const weightsY = smBadgeY + 18 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, weightsY, 'weights', `[3]`,
    COLORS.retrieval.fill, COLORS.retrieval.stroke, 120);
  arrowDown(grp, cx, smBadgeY + 18, weightsY - VEC_H / 2, COLORS.retrieval.stroke);

  drawShapeEq(grp, cx, weightsY + VEC_H / 2 + 30,
    `q_enc [1,${p.dModel}] · index^T [${p.dModel},3] → scores [3] → softmax → weights [3]`,
    COLORS.retrieval.stroke);

  return { bottom: weightsY + VEC_H / 2 + 48, outCy: weightsY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Advanced RAG variant step functions
// ═══════════════════════════════════════════════════════════════════════════════

function drawQueryRewriteStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, inputBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-rewrite', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Query Rewriting',
    `q' = SiLU(query @ W_rewrite)`,
    COLORS.encoder.fill, COLORS.encoder.stroke
  );
  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  drawWeightMatrix(grp, cx, wCy, 'W_rewrite', `[${p.dModel}, ${p.dModel}]`,
    COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, cx, inputBottom, wCy - WEIGHT_H / 2, COLORS.encoder.stroke);

  const actY = wCy + WEIGHT_H / 2 + ROW_EQ_GAP / 2 + 18;
  drawBadge(grp, cx, actY, 'SiLU', COLORS.encoder.fill, COLORS.encoder.stroke);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, actY - 18, COLORS.encoder.stroke);

  const qRewY = actY + 18 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, qRewY, "q'", `[1, ${p.dModel}]`,
    COLORS.encoder.fill, COLORS.encoder.stroke);
  arrowDown(grp, cx, actY + 18, qRewY - VEC_H / 2, COLORS.encoder.stroke);

  drawShapeEq(grp, cx, qRewY + VEC_H / 2 + 30,
    `query [${p.seqLen},${p.dModel}] · W_rewrite [${p.dModel},${p.dModel}] → SiLU → q' [1,${p.dModel}]`,
    COLORS.encoder.stroke);

  return { bottom: qRewY + VEC_H / 2 + 48, outCy: qRewY };
}

function drawFirstHopRetrievalStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, qRewCy: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-hop1', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'First-hop Retrieval',
    `hop1 = retrieve(q', k=${p.kDocs})`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const ctxCy = headerBottom + BOX_TO_ROW_GAP + 50;
  drawDocIndex(grp, cx, ctxCy, 'hop1_ctx', `[${p.kDocs}, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  arrowDown(grp, cx, qRewCy + VEC_H / 2, ctxCy - 50, COLORS.encoder.stroke);
  lbl(grp, cx, ctxCy + 50 + 18, 'first-pass retrieval: top-k docs for rewritten query', { size: 9, color: COLORS.muted });
  return { bottom: ctxCy + 50 + 30, outCy: ctxCy };
}

function drawReRankingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  _qRewCy: number, _hop1Cy: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-rerank', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Re-ranking',
    `rerank = softmax(q' @ hop1^T)`,
    COLORS.rerank.fill, COLORS.rerank.stroke
  );
  const rowY = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  const qX = cx - 160;
  const hX = cx + 160;

  drawSmallVector(grp, qX, rowY, "q'", `[1, ${p.dModel}]`,
    COLORS.encoder.fill, COLORS.encoder.stroke, 120);
  drawDocIndex(grp, hX, rowY, 'hop1', `[${p.kDocs}, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke);
  drawBadge(grp, cx, rowY, '@', COLORS.rerank.fill, COLORS.rerank.stroke);
  arrowH(grp, qX + 60, rowY, cx - 30, COLORS.encoder.stroke);
  arrowH(grp, hX - 100, rowY, cx + 30, COLORS.document.stroke);

  const scoresY = rowY + 50 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, scoresY, 'scores', `[${p.kDocs}]`,
    COLORS.rerank.fill, COLORS.rerank.stroke, 120);
  arrowDown(grp, cx, rowY + 18, scoresY - VEC_H / 2, COLORS.rerank.stroke);

  const smY = scoresY + VEC_H / 2 + 18 + 18;
  drawBadge(grp, cx, smY, 'softmax', COLORS.rerank.fill, COLORS.rerank.stroke);
  arrowDown(grp, cx, scoresY + VEC_H / 2, smY - 18, COLORS.rerank.stroke);

  const rerankedY = smY + 18 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, rerankedY, 'reranked', `[${p.kDocs}]`,
    COLORS.rerank.fill, COLORS.rerank.stroke, 120);
  arrowDown(grp, cx, smY + 18, rerankedY - VEC_H / 2, COLORS.rerank.stroke);

  drawShapeEq(grp, cx, rerankedY + VEC_H / 2 + 30,
    `q' [1,${p.dModel}] · hop1^T [${p.dModel},${p.kDocs}] → scores [${p.kDocs}] → softmax → reranked [${p.kDocs}]`,
    COLORS.rerank.stroke);

  return { bottom: rerankedY + VEC_H / 2 + 48, outCy: rerankedY };
}

function drawSecondHopRetrievalStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams, rerankedCy: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-hop2', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Second-hop Retrieval',
    `hop2 = retrieve(top_doc, k=1)`,
    COLORS.document.fill, COLORS.document.stroke
  );
  const docCy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, docCy, 'hop2_doc', `[1, ${p.dModel}]`,
    COLORS.document.fill, COLORS.document.stroke, 160);
  arrowDown(grp, cx, rerankedCy + VEC_H / 2, docCy - VEC_H / 2, COLORS.rerank.stroke);
  lbl(grp, cx, docCy + VEC_H / 2 + 14, 'second-pass retrieval using top-ranked doc', { size: 9, color: COLORS.muted });
  return { bottom: docCy + VEC_H / 2 + 30, outCy: docCy };
}

function drawMultiHopFusionStep(
  g: Gsel, cx: number, y: number, stepId: number, p: RagParams,
  hop1Cy: number, hop2Cy: number, queryBypassY: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-rag-fusion', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, 'Multi-hop Fusion',
    `context = [hop1; hop2; query]`,
    COLORS.augment.fill, COLORS.augment.stroke
  );
  const concatY = headerBottom + BOX_TO_ROW_GAP + 18;
  opCircle(grp, cx, concatY, '⊕', COLORS.augment.stroke);
  lbl(grp, cx + 22, concatY, 'concat', { size: 9, color: COLORS.muted, anchor: 'start' });

  drawDashedPath(g,
    `M ${cx},${hop1Cy + 50} L ${cx + 260},${hop1Cy + 50} L ${cx + 260},${concatY} L ${cx + 16},${concatY}`,
    COLORS.document.stroke, 0.4);
  lbl(g, cx + 268, (hop1Cy + 50 + concatY) / 2, 'hop1 ctx',
    { size: 9, color: COLORS.document.stroke, anchor: 'start' });
  arrowDown(grp, cx + 80, hop2Cy + VEC_H / 2, concatY - 16, COLORS.document.stroke);

  if (queryBypassY > 0) {
    drawDashedPath(g,
      `M ${CX - SEQ_W / 2 - 10},${queryBypassY} L ${BYPASS_FAR_X},${queryBypassY} L ${BYPASS_FAR_X},${concatY} L ${cx + 16},${concatY}`,
      COLORS.input.stroke, 0.6);
    lbl(g, BYPASS_FAR_X - 8, (queryBypassY + concatY) / 2, 'query bypass',
      { size: 9, color: COLORS.input.stroke, anchor: 'end' });
  }

  const ctxY = concatY + 18 + ROW_EQ_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, ctxY, 'context', `[${p.kDocs + 1}, ${p.dModel}]`,
    COLORS.augment.fill, COLORS.augment.stroke);
  arrowDown(grp, cx, concatY + 16, ctxY - MAT_H / 2, COLORS.augment.stroke);
  lbl(grp, cx, ctxY + MAT_H / 2 + 18, 'fused multi-hop context for generation', { size: 9, color: COLORS.muted });

  return { bottom: ctxY + MAT_H / 2 + 30, outCy: ctxY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderRagPipeline(g: Gsel, cx: number, y: number, p: RagParams): RenderResult {
  const steps: RagStep[] = [];
  let stepId = 1;

  const input = drawInputQueryStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Input', 'Input Query', `query: [${p.seqLen}, ${p.dModel}]`,
    'User question tokenized into a sequence of hidden-state vectors.', 'step-rag-input',
    COLORS.input.stroke, COLORS.input.fill));
  stepId++;
  const queryBypassY = input.outCy;
  y = input.bottom + GROUP_GAP;

  const qenc = drawQueryEncodingStep(g, cx, y, stepId, p, input.bottom);
  steps.push(makeStep(stepId, 'Q-Enc', 'Query Encoding', `q_emb = mean(query @ W_enc)`,
    'Encode the query into a single dense embedding vector via a linear projection + mean pooling.', 'step-rag-qenc',
    COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = qenc.bottom + GROUP_GAP;

  const docidx = drawDocIndexStep(g, cx, y, stepId, p, 'Document Index');
  steps.push(makeStep(stepId, 'Doc Index', 'Document Index', `D ∈ ℝ^(${p.nDocs}, ${p.dModel})`,
    'Pre-computed embeddings for all documents in the corpus, stored in a vector index (FAISS/HNSW).', 'step-rag-docidx',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = docidx.bottom + GROUP_GAP;

  const retrieval = drawSimilarityRetrievalStep(g, cx, y, stepId, p, qenc.outCy, docidx.outCy);
  steps.push(makeStep(stepId, 'Retrieve', 'Similarity & Retrieval', `scores = cos(q_emb, D) → top-k`,
    'Compute cosine similarity between query embedding and all document embeddings, then select top-k most relevant docs.', 'step-rag-retrieval',
    COLORS.retrieval.stroke, COLORS.retrieval.fill));
  stepId++;
  y = retrieval.bottom + GROUP_GAP;

  const aug = drawAugmentationStep(g, cx, y, stepId, p, retrieval.outCy + VEC_H / 2 + 20, queryBypassY);
  steps.push(makeStep(stepId, 'Augment', 'Context Augmentation', `context = [docs; query]`,
    'Concatenate retrieved document chunks with the original query to form the LLM prompt context.', 'step-rag-augment',
    COLORS.augment.stroke, COLORS.augment.fill));
  stepId++;
  y = aug.bottom + GROUP_GAP;

  const gen = drawGenerationStep(g, cx, y, stepId, p, aug.outCy + MAT_H / 2 + 20);
  steps.push(makeStep(stepId, 'Generate', 'LLM Generation', `answer = LLM.generate(context)`,
    'The LLM autoregressively generates an answer conditioned on the augmented context.', 'step-rag-gen',
    COLORS.generate.stroke, COLORS.generate.fill));
  stepId++;
  y = gen.bottom + GROUP_GAP;

  const out = drawOutputStep(g, cx, y, stepId, p, gen.outCy + VEC_H / 2 + 20);
  steps.push(makeStep(stepId, 'Output', 'Output Answer', `answer ∈ ℝ^(seq_a)`,
    'Generated response returned to the user.', 'step-rag-output',
    COLORS.output.stroke, COLORS.output.fill));

  return { steps, y: out, queryBypassY };
}

function renderChunking(g: Gsel, cx: number, y: number, p: RagParams): RenderResult {
  const steps: RagStep[] = [];
  let stepId = 1;

  const input = drawInputQueryStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Input', 'Input Query', `query: [${p.seqLen}, ${p.dModel}]`,
    'User question tokenized into hidden-state vectors.', 'step-rag-input',
    COLORS.input.stroke, COLORS.input.fill));
  stepId++;
  const queryBypassY = input.outCy;
  y = input.bottom + GROUP_GAP;

  const rawdoc = drawRawDocStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'RawDoc', 'Raw Document', `raw_doc: [${p.seqLen * 4}, ${p.dModel}]`,
    'Source document to be chunked and indexed.', 'step-rag-rawdoc',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = rawdoc.bottom + GROUP_GAP;

  const chunking = drawChunkingStep(g, cx, y, stepId, p, rawdoc.bottom);
  steps.push(makeStep(stepId, 'Chunk', 'Document Chunking', `chunks = split(raw_doc, size=${p.seqLen})`,
    'Split the raw document into overlapping chunks for fine-grained retrieval.', 'step-rag-chunk',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = chunking.bottom + GROUP_GAP;

  const chunkenc = drawChunkEncodingStep(g, cx, y, stepId, p, chunking.chunksCy, chunking.chunkXs);
  steps.push(makeStep(stepId, 'ChunkEnc', 'Chunk Encoding', `emb_i = mean(chunk_i @ W_enc)`,
    'Encode each chunk into a single dense embedding via W_enc + mean pooling.', 'step-rag-chunkenc',
    COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = chunkenc.bottom + GROUP_GAP;

  const index = drawIndexBuildingStep(g, cx, y, stepId, p, chunkenc.embsCy, chunkenc.embXs);
  steps.push(makeStep(stepId, 'Index', 'Index Building', `index = stack(emb_0, emb_1, emb_2)`,
    'Stack chunk embeddings to form a searchable vector index.', 'step-rag-index',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = index.bottom + GROUP_GAP;

  const qenc = drawQueryEncodingStep(g, cx, y, stepId, p, input.bottom);
  steps.push(makeStep(stepId, 'Q-Enc', 'Query Encoding', `q_enc = mean(query @ W_enc)`,
    'Encode the query using the same encoder used for chunks.', 'step-rag-qenc',
    COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = qenc.bottom + GROUP_GAP;

  const retrieval = drawRetrievalMatMulStep(g, cx, y, stepId, p, qenc.outCy, index.outCy);
  steps.push(makeStep(stepId, 'Retrieve', 'Retrieval (MatMul + Softmax)', `scores = q_enc @ index^T → softmax`,
    'Compute similarity scores via matmul, then softmax to get retrieval weights.', 'step-rag-matmul',
    COLORS.retrieval.stroke, COLORS.retrieval.fill));
  stepId++;
  y = retrieval.bottom + GROUP_GAP;

  const aug = drawAugmentationStep(g, cx, y, stepId, p, retrieval.outCy + VEC_H / 2 + 20, queryBypassY);
  steps.push(makeStep(stepId, 'Augment', 'Context Augmentation', `augmented = query + weights @ index`,
    'Augment the query with weighted document embeddings.', 'step-rag-augment',
    COLORS.augment.stroke, COLORS.augment.fill));
  stepId++;
  y = aug.bottom + GROUP_GAP;

  const out = drawOutputStep(g, cx, y, stepId, p, aug.outCy + MAT_H / 2 + 20);
  steps.push(makeStep(stepId, 'Output', 'Output Answer', `out ∈ ℝ^(${p.seqLen}, ${p.dModel})`,
    'Augmented representation passed to the downstream model.', 'step-rag-output',
    COLORS.output.stroke, COLORS.output.fill));

  return { steps, y: out, queryBypassY };
}

function renderAdvanced(g: Gsel, cx: number, y: number, p: RagParams): RenderResult {
  const steps: RagStep[] = [];
  let stepId = 1;

  const input = drawInputQueryStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Input', 'Input Query', `query: [${p.seqLen}, ${p.dModel}]`,
    'User question tokenized into hidden-state vectors.', 'step-rag-input',
    COLORS.input.stroke, COLORS.input.fill));
  stepId++;
  const queryBypassY = input.outCy;
  y = input.bottom + GROUP_GAP;

  const rewrite = drawQueryRewriteStep(g, cx, y, stepId, p, input.bottom);
  steps.push(makeStep(stepId, 'Rewrite', 'Query Rewriting', `q' = SiLU(query @ W_rewrite)`,
    'Rewrite/expand the query to improve retrieval quality.', 'step-rag-rewrite',
    COLORS.encoder.stroke, COLORS.encoder.fill));
  stepId++;
  y = rewrite.bottom + GROUP_GAP;

  const hop1 = drawFirstHopRetrievalStep(g, cx, y, stepId, p, rewrite.outCy);
  steps.push(makeStep(stepId, 'Hop1', 'First-hop Retrieval', `hop1 = retrieve(q', k=${p.kDocs})`,
    'Retrieve top-k documents using the rewritten query.', 'step-rag-hop1',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = hop1.bottom + GROUP_GAP;

  const rerank = drawReRankingStep(g, cx, y, stepId, p, rewrite.outCy, hop1.outCy);
  steps.push(makeStep(stepId, 'Rerank', 'Re-ranking', `rerank = softmax(q' @ hop1^T)`,
    'Re-rank first-hop docs by computing similarity with the rewritten query.', 'step-rag-rerank',
    COLORS.rerank.stroke, COLORS.rerank.fill));
  stepId++;
  y = rerank.bottom + GROUP_GAP;

  const hop2 = drawSecondHopRetrievalStep(g, cx, y, stepId, p, rerank.outCy);
  steps.push(makeStep(stepId, 'Hop2', 'Second-hop Retrieval', `hop2 = retrieve(top_doc, k=1)`,
    'Use the top-ranked document to retrieve additional relevant context.', 'step-rag-hop2',
    COLORS.document.stroke, COLORS.document.fill));
  stepId++;
  y = hop2.bottom + GROUP_GAP;

  const fusion = drawMultiHopFusionStep(g, cx, y, stepId, p, hop1.outCy, hop2.outCy, queryBypassY);
  steps.push(makeStep(stepId, 'Fuse', 'Multi-hop Fusion', `context = [hop1; hop2; query]`,
    'Concatenate first-hop, second-hop, and query into a unified context.', 'step-rag-fusion',
    COLORS.augment.stroke, COLORS.augment.fill));
  stepId++;
  y = fusion.bottom + GROUP_GAP;

  const gen = drawGenerationStep(g, cx, y, stepId, p, fusion.outCy + MAT_H / 2 + 20);
  steps.push(makeStep(stepId, 'Generate', 'LLM Generation', `answer = LLM.generate(context)`,
    'Generate the final answer conditioned on the fused multi-hop context.', 'step-rag-gen',
    COLORS.generate.stroke, COLORS.generate.fill));
  stepId++;
  y = gen.bottom + GROUP_GAP;

  const out = drawOutputStep(g, cx, y, stepId, p, gen.outCy + VEC_H / 2 + 20);
  steps.push(makeStep(stepId, 'Output', 'Output Answer', `answer ∈ ℝ^(seq_a)`,
    'Generated response returned to the user.', 'step-rag-output',
    COLORS.output.stroke, COLORS.output.fill));

  return { steps, y: out, queryBypassY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Step factory helper
// ═══════════════════════════════════════════════════════════════════════════════

function makeStep(
  id: number, shortLabel: string, label: string, formula: string,
  explanation: string, svgGroup: string, color: string, fill: string,
  codeLines?: string[]
): RagStep {
  return {
    id, label, shortLabel, formula, explanation,
    code: { title: label, lines: codeLines || [`# ${formula}`] },
    svgGroup, color, fill,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Metrics
// ═══════════════════════════════════════════════════════════════════════════════

function computeMetrics(p: RagParams) {
  const encParams = p.dModel * p.dModel;
  const indexSize = p.nDocs * p.dModel;
  const retrievalFlops = 2 * p.nDocs * p.dModel;
  const encodeFlops = 2 * p.seqLen * p.dModel * p.dModel;
  const totalRagParams = encParams;
  return { encParams, indexSize, retrievalFlops, encodeFlops, totalRagParams };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderRagArchitectureDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 64;
  const kDocs = Number(params.k_docs) || 3;
  const variant = String(params.variant || 'rag_pipeline');
  const nDocs = kDocs * 3 + 1;

  const p: RagParams = { dModel, seqLen, kDocs, nDocs, variant };

  const root = g as unknown as Gsel;
  let y = 28;

  const variantLabel = variant === 'chunking' ? 'Chunking & Retrieval'
    : variant === 'advanced' ? 'Advanced RAG (multi-hop + re-ranking)'
    : 'RAG Pipeline (encode → retrieve → generate)';

  lbl(root, CX, y, 'Retrieval-Augmented Generation (RAG)', { size: 18, weight: '700', color: COLORS.text });
  y += 22;
  lbl(root, CX, y,
    `${variantLabel} · d_model=${dModel} · seq_len=${seqLen} · k_docs=${kDocs} · n_docs=${nDocs}`,
    { size: 11, color: COLORS.muted });
  y += 28;

  y = drawParamSummary(root, CX, y, p);
  y += 16;

  let result: RenderResult;
  if (variant === 'chunking') {
    result = renderChunking(root, CX, y, p);
  } else if (variant === 'advanced') {
    result = renderAdvanced(root, CX, y, p);
  } else {
    result = renderRagPipeline(root, CX, y, p);
  }

  let footerY = result.y + 20;

  const metrics = computeMetrics(p);
  lbl(root, CX, footerY + 16,
    `Encoder: ${fmtNum(metrics.encParams)} params · Index: ${fmtNum(metrics.indexSize)} floats · ~${fmtNum(metrics.retrievalFlops)} retrieval FLOPs · ~${fmtNum(metrics.encodeFlops)} encoding FLOPs`,
    { size: 11, color: COLORS.muted, font: 'monospace' });
  footerY += 38;

  const insightText = variant === 'chunking'
    ? 'Chunking splits long documents into overlapping segments (typically 256-512 tokens with 10-20% overlap) so retrieval can pinpoint relevant passages rather than whole documents. Smaller chunks improve precision but increase index size; overlap prevents context fragmentation at boundaries.'
    : variant === 'advanced'
    ? 'Advanced RAG adds query rewriting (expand/reformulate for better recall), multi-hop retrieval (follow chains of evidence across documents), and cross-encoder re-ranking (score docs against the query with a more expensive but more accurate model). This trades latency for precision.'
    : 'RAG combines parametric knowledge (LLM weights) with non-parametric knowledge (retrieved documents). The query is encoded into a dense vector, compared against a pre-computed document index via cosine similarity, and the top-k results are concatenated with the query to form the generation context.';

  const perfText = variant === 'chunking'
    ? `Encoding cost: O(chunks × seq × d²) = ${fmtNum(3 * seqLen * dModel * dModel)} FLOPs. Retrieval: O(chunks × d) = ${fmtNum(3 * dModel)} FLOPs. ANN index (HNSW) achieves O(log N) search vs O(N) brute-force.`
    : variant === 'advanced'
    ? `Two retrieval passes: O(2 × N × d) = ${fmtNum(2 * nDocs * dModel)} FLOPs for retrieval. Re-ranking adds O(k × d) = ${fmtNum(kDocs * dModel)} FLOPs. Total latency ≈ 2× single-hop RAG + re-ranker forward pass.`
    : `Brute-force retrieval: O(N × d) = ${fmtNum(nDocs * dModel)} FLOPs (${nDocs} docs × ${dModel} dims). ANN (HNSW/FAISS) reduces this to O(log N × d). Generation dominates end-to-end latency (autoregressive decode).`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = variant === 'chunking' ? [
    '# Chunking & Retrieval',
    `chunks = split_overlap(raw_doc, size=${seqLen}, stride=${Math.floor(seqLen * 0.8)})`,
    `chunk_embs = [mean(c @ W_enc) for c in chunks]  # [3, ${dModel}]`,
    'index = torch.stack(chunk_embs)                  # [3, d_model]',
    `q_enc = mean(query @ W_enc)                      # [1, ${dModel}]`,
    'scores = q_enc @ index.T                         # [3]',
    'weights = F.softmax(scores, dim=-1)              # [3]',
    'augmented = query + weights @ index              # [seq, d_model]',
  ] : variant === 'advanced' ? [
    '# Advanced RAG (multi-hop + re-ranking)',
    `q_rewritten = F.silu(query @ W_rewrite)          # [1, ${dModel}]`,
    `hop1 = retrieve(q_rewritten, k=${kDocs})          # [${kDocs}, ${dModel}]`,
    'rerank_scores = q_rewritten @ hop1.T             # [k_docs]',
    'reranked = F.softmax(rerank_scores, dim=-1)      # [k_docs]',
    'top_doc = hop1[reranked.argmax()]',
    'hop2 = retrieve(top_doc, k=1)                    # [1, d_model]',
    'context = concat(hop1, hop2, query)              # [k+2, d_model]',
    'answer = llm.generate(context)',
  ] : [
    '# RAG Pipeline (Lewis et al. 2020)',
    `q_emb = mean(query @ W_enc)                      # [1, ${dModel}]`,
    `scores = cosine_sim(q_emb, doc_index)            # [${nDocs}]`,
    `top_k = scores.topk(k=${kDocs})                  # [${kDocs}]`,
    'retrieved = [corpus[i] for i in top_k.indices]',
    'context = format_prompt(retrieved, query)',
    'answer = llm.generate(context)                   # autoregressive',
  ];

  footerY = drawCodeAnnotation(
    g, 80, footerY, W - 160,
    `RAG — ${variantLabel}`,
    [`Encoder: ${fmtNum(metrics.encParams)} params · Index: ${fmtNum(metrics.indexSize)} floats`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps: result.steps };
}
